"""Unit 4.2: original mechanism diagrams and evidence-led captions."""
from atlas_figures import shell
from unit4_mobile import drawing as mobile_drawing

LESSONS = [
    {'title': 'Blocking vs nonblocking I/O', 'caption': 'With no bytes ready, a blocking call keeps its thread waiting. A nonblocking call returns “not ready”; a readiness notification tells the program when to try again. Neither return nor readiness means the whole file has arrived.'},
    {'title': 'Concurrency is not parallelism', 'caption': 'On one core, A and B alternate. On two cores, their execution overlaps. The first is concurrent progress; the second also demonstrates parallel execution.'},
    {'title': 'Follow a task through the event loop', 'caption': 'A submits I/O and suspends. The loop runs other ready work, then makes A ready after completion. A long callback prevents this one thread from attending to other ready tasks.'},
    {'title': 'The bounded worker pool', 'caption': 'J1 and J2 occupy both workers; J3–J5 occupy all three waiting slots. J6 therefore requires an overload response. A worker limit alone does not bound the waiting queue.'},
]

