def drawing(n, j, k, index):
    item = LESSONS[index]
    return shell(n, j, k, item['title'], SVGS[index], item['caption'],
                 'Trace the objects, states and ordering described in the caption.',
                 height=320, mobile=mobile_drawing(2, index))
